const $ = (id) => document.getElementById(id);
let st = { zikr: 'سبحان الله', counts: {}, goal: 33, total: 0 };
const cur = () => st.counts[st.zikr] || 0;
const save = () => Alaisai.set('state', st);
function render() {
  $('zikr').textContent = st.zikr; $('n').textContent = cur();
  $('of').textContent = st.goal ? `من ${st.goal}` : 'بلا حدّ';
  $('tap').classList.toggle('full', !!st.goal && cur() >= st.goal);
  $('goal').value = String(st.goal);
  $('total').textContent = `الإجمالي الكلي: ${st.total}`;
  document.querySelectorAll('[data-z]').forEach((b) => b.setAttribute('aria-pressed', b.dataset.z === st.zikr));
}
$('tap').onclick = () => {
  st.counts[st.zikr] = cur() + 1; st.total++;
  if (st.goal && cur() === st.goal) { Alaisai.toast('تقبّل الله، أتممت ' + st.goal); try { navigator.vibrate && navigator.vibrate(120); } catch (_) {} }
  save(); render();
};
$('reset').onclick = () => { st.counts[st.zikr] = 0; save(); render(); };
$('goal').onchange = (e) => { st.goal = +e.target.value; save(); render(); };
document.querySelectorAll('[data-z]').forEach((b) => (b.onclick = () => { st.zikr = b.dataset.z; save(); render(); }));
Alaisai.get('state').then((v) => {
  if (v && typeof v === 'object') st = { zikr: typeof v.zikr === 'string' ? v.zikr : st.zikr, counts: v.counts && typeof v.counts === 'object' ? v.counts : {}, goal: [0, 33, 99, 100].includes(v.goal) ? v.goal : 33, total: +v.total || 0 };
  render();
}).catch(render);

.tz{max-width:420px;margin:0 auto;padding:16px;text-align:center}
.presets{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-bottom:12px}
button,select{font:inherit}
.presets button,#reset,select{min-height:44px;padding:6px 14px;border-radius:12px;border:1px solid var(--line);background:var(--card);color:var(--fg);cursor:pointer}
.presets [aria-pressed=true]{background:var(--accent);color:var(--accent-fg);border-color:var(--accent);font-weight:700}
.zikr{font-size:1.8rem;margin:8px 0 16px}
.tap{width:220px;height:220px;border-radius:50%;border:6px solid var(--accent);background:var(--card);color:var(--fg);cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;margin:0 auto;box-shadow:0 8px 24px rgba(0,0,0,.15);transition:transform .08s}
.tap:active{transform:scale(.96)}
.tap span{font-size:4rem;font-weight:700;font-variant-numeric:tabular-nums}
.tap small{color:var(--muted)}
.tap.full{background:var(--accent);color:var(--accent-fg)}.tap.full small{color:var(--accent-fg)}
.row{display:flex;gap:12px;justify-content:center;align-items:center;margin:18px 0}
.muted{color:var(--muted)}
:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
